{
  "phiếu_chăm sóc": {
    "thông_tin_bệnh_nhân": {
      "họ_tên": "[Nguyễn Văn A]<human_name>",
      "ngày_sinh": "[15/03/1956]<date>",
      "mã_bệnh_nhân": "[BN12345678]<id_number>",
