      "địa_chỉ": "[Số 12 Đường Phan Đình Phùng, Phường 1, Quận 1, TP.HCM]<address>",
      "số_điện_thoại": "[0901234567]<phone_number>"
    },
    "thông_tin_chỉ định": {
      "bác_sĩ_chỉ định": "[Trần Thị B]<human_name>",
      "khoa": "Khoa Nội Tim Mạch",
      "ngày_chỉ định": "[20/10/2023]<date>",
      "bệnh_viện": "Bệnh viện Chợ Rẫy",
      "email_liên_lạc": "[noibong@chouray.com]<email_address>"
    },
    "nội_dung_chăm sóc": "Bệnh nhân Nguyễn Văn A (78 tuổi) được chỉ định truyền dịch Digoxin 0.25mg. Đều đặn hàng ngày, điều dưỡng viên Lê Văn C (Mã NV: 98765) đến kiểm tra các chỉ số sinh hiệu: huyết áp 130/85 mmHg, nhịp tim 78 lần/phút, nhiệt độ 37.1°C, SpO2 97%. Bệnh nhân có biểu hiện mệt mỏi, ho khan. Đánh giá ban đầu cho thấy tình trạng khó thở nhẹ đã giảm sau khi dùng thuốc. Ghi chú: Cần theo dõi sát nhịp tim và triệu chứng ngộ độc Digitalis.",
    "chuyên_gia_liên_khoa": {
      "ý_kiến_chuyên_môn_tim_mạch": "Ý kiến của BS. Nguyễn Văn D (Khoa Tim Mạch, BV Chợ Rẫy) vào lúc 14h30 ngày [20/10/2023]<date>: \"Tiếp tục theo dõi sát điện tâm đồ và men tim. Không cần thay đổi liều Digoxin hiện tại (0.25mg/ngày).\"",
      "đánh_giá_dược_lâm_sàng": "BS. Lê Thị E (Dược sĩ lâm sàng, Công ty Dược Phẩm Gia Định) khuyến nghị: \"Cân chỉnh liều Furosemide từ 40mg lên 80mg dựa trên tình trạng phù phổi nhẹ quan sát thấy.\"",
      "phối_hợp_hồi_sức": "BV Đa khoa Quốc tế C (Email: contact@internationalhospital.com) đề nghị hội chẩn thêm nếu chỉ số Creatinine tiếp tục tăng."
    },
    "chữ_ký": {
      "người_thực_hiện": "[Lê Văn C]<human_name>",
      "mã_điều_dưỡng": "[NV98765]<id_number>",
      "thời_gian_ký": "[21/10/2023 08:00]<date>"
    }
  }
}

