      "dien_thoai_nguoi_than": "[0903 112 998]<phone_number>",
      "dia_chi_thuong_tru": "[Số 45, Ấp Mỹ Thới, Xã Mỹ Khánh, Huyện Phong Điền, Thành phố Cần Thơ]<address>",
      "ma_benh_nhan_noi_bo": "[BN-88422-K]<id_number>",
      "so_can_cuoc_cong_dan": "[079204001234]<id_number>",
      "so_bao_hiem_y_te": "[KH2345678901234]<id_number>",
      "ma_dinh_danh_fhir": "urn:uuid:1e4b7c9a-5d8f-4e2a-bc12-3f9a8b2c4d5e"
    },
    "nguoi_chuyen_tuyen": {
      "ten_bac_si_chuyen": "[Nguyễn Thanh Tùng]<human_name>",
      "chuc_danh": "Thạc sĩ - Bác sĩ CKII",
      "so_chung_chi_hanh_nghe": "[23455/NL-BV]<id_number>",
      "ky_ten_dien_tu": "[BS. Nguyễn Thanh Tùng]<human_name>"
    },
    "ly_do_chuyen_tuyen": {
      "chan_doan_ra_vien": "Cao huyết áp cấp độ 3, Rối loạn lipid máu, Đái tháo đường type 2 không tuân thủ điều trị.",
      "tom_tat_benh_su": "Bệnh nhân có tiền sử đái tháo đường 10 năm, tăng huyết áp 15 năm. Tự ý ngưng thuốc thuốc Metformin và Amlodipine 3 tháng trước. Vào lúc 02h00 ngày 15/10/2024, bệnh nhân xuất hiện đau ngực dữ dội vùng trước tim, vã mồ hôi, khó thở. Được đưa vào khoa Cấp cứu của bệnh viện lúc 03h15. Điện tâm đồ ghi nhận ST chênh lên đỉnh trước tim. Xét nghiệm Troponin tăng cao.",
      "dien_bien_lam_sang": "Sau 8 giờ điều trị tích cực bằng thuốc tiêu sợi huyết (Alteplase) và Nitroglycerin truyền tĩnh mạch, triệu chứng đau ngực giảm đáng kể. Tuy nhiên, huyết áp vẫn dao động không ổn định (160/100 mmHg), có giai đoạn nhịp nhanh kịch phát trên thất (SVT) kéo dài 15 phút, đã được chẹn bằng Adenosine. Triệu chứng khó thở tái phát nhẹ khi gắng sức.",
      "thuoc_dang_dung": "Aspirin 80mg, Clopidogrel 75mg, Atorvastatin 40mg, Eplerenone 50mg, Insulin Glargine.",
      "dien_tien_trong_vien": "Ngày 16/10: Huyết áp ổn định 140/90 mmHg. Ngày 17/10: Triệu chứng lâm sàng cơ bản ổn định. CT não không có dấu hiệu chảy máu.",
      "can_thiep_da_thao_duong": "Theo dõi đường huyết mao mạch, tiêm Insulin theo phác đồ.",
      "chi_dinh_chuyen_tuyen": "Chuyển tuyến cấp cứu lên Khoa Tim Mạch Can thiệp để theo dõi sát và can thiệp động mạch vành nếu cần thiết, đồng thời điều chỉnh phác đồ đái tháo đường.",
      "y_kien_cua_bac_si_chuyen": "Bệnh nhân có nguy cơ cao nhồi máu cơ tim tái phát. Cần làm nhánh mạc xanh tim mạch để đánh giá lại mức độ hẹp.",
      "ngay_gio_chuyen": "[17/10/2024 14:15]<date>"
    },
